raw = [10, 0, 20, None, -2]
valid = []
rejected = 0
for value in raw:
    if type(value) is int and 0 <= value <= 60:
        valid.append(value)
    else:
        rejected = rejected + 1
print(len(valid), rejected)
if len(valid) > 0:
    print(sum(valid) / len(valid))
else:
    print("No valid observations")
